tool.command:
        mkdir -p metadavis_inputs ;
#if $otu_table
        cp -f '$otu_table' metadavis_inputs/otu ;
#end if
#if $taxonomy_table
        cp -f '$taxonomy_table' metadavis_inputs/taxonomy ;
#end if
#if $metadata_table
        cp -f '$metadata_table' metadavis_inputs/metadata ;
        rm -f metadavis_inputs/metadata_trimmed metadavis_trim.txt ;
        METADAVIS_TRIM_NOTE_FILE=metadavis_trim.txt metadavis-trim-metadata metadavis_inputs/metadata '$condition_column' metadavis_inputs/metadata_trimmed &&
        ln -sf metadata_trimmed metadavis_inputs/metadata || true ;
#end if
        exec /usr/local/bin/metadavis-entrypoint
